def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each colored cell expands into a 3x3 copy of the zero-mask of the input.
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                for dr in range(h):
                    for dc in range(w):
                        if grid[dr][dc] == 0:
                            out[3 * r + dr][3 * c + dc] = color
    return out
